  @PrimaryGeneratedColumn() id!: number
  @OneToMany(() => OrderLine, (l) => l.order,
             { cascade: true, orphanedRowAction: "delete", eager: true })
  lines!: OrderLine[]
}
const order = await dataSource.manager.findOneByOrFail(Order, { id });
order.lines.pop();
await dataSource.manager.save(order);   // graph saved once

